    string private _symbol;
    uint8 private _decimals;

    /* START ALPHA CHANGE 266 -- restrict emergency block reward issuance to configured issuer -- */
    modifier onlyBlockRewardIssuer() {
        require(msg.sender == _blockRewardIssuer, "INNBCNativeToken: only block reward issuer can call");

