     */
    function initialize(
        address predicate_,
        address blockRewardIssuer_,
        address rootToken_,
        string calldata name_,
        string calldata symbol_,
        uint8 decimals_,
        uint256 tokenSupply_
    ) external virtual initializer onlySystemCall {
        /* START ALPHA CHANGE 267 -- initialize block reward issuer instead of centralized owner -- */
        require(blockRewardIssuer_ != address(0), "INNBCNativeToken: invalid block reward issuer");
        // slither-disable-next-line missing-zero-check,events-access
        _predicate = predicate_;
        _blockRewardIssuer = blockRewardIssuer_;
        /* FINISH ALPHA CHANGE 267 -- initialize block reward issuer instead of centralized owner -- */
        // slither-disable-next-line missing-zero-check
        _rootToken = rootToken_; // root token should be set to zero where no root token exists
        _name = name_;
        _symbol = symbol_;
        // slither-disable-next-line events-maths
        _decimals = decimals_;
        _totalSupply = tokenSupply_;
    }

    /**
     * @dev See {IERC20-transfer}.
     *
