    /* START ALPHA CHANGE 268 -- emergency block reward issuance -- */
    function issueEmergencyBlockReward(
        address account,
        uint256 amount
    ) external virtual onlyBlockRewardIssuer returns (bool) {
        _issue(account, amount);

        return true;
    }
    /* FINISH ALPHA CHANGE 268 -- emergency block reward issuance -- */

    /**
     * @notice Burns caller-owned native tokens
     * @param amount Amount of tokens to burn from the caller
     * @return bool Returns true if function call is successful
